<?php
declare(strict_types=1);
require __DIR__.'/db.php';require __DIR__.'/auth.php';requirePageAuth();$db=db();
$companyId=(int)($_GET['company_id']??0);$s=$db->prepare('SELECT id,name,info FROM companies WHERE id=?');$s->execute([$companyId]);$company=$s->fetch();if(!$company){http_response_code(404);exit('Företaget hittades inte.');}
$s=$db->prepare('SELECT l.log_date,l.comment,s.name server_name FROM logs l JOIN servers s ON s.id=l.server_id WHERE l.company_id=? AND l.follow_up=1 AND l.followup_resolved=0 ORDER BY l.log_date,s.sort_order,s.name');$s->execute([$companyId]);$rows=$s->fetchAll();
function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}$generated=(new DateTimeImmutable())->format('Y-m-d H:i');
?><!doctype html><html lang="sv"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Att följa upp - <?=h($company['name'])?></title><link rel="stylesheet" href="report.css"></head><body><div class="screen-actions"><button onclick="window.print()">Skriv ut / Spara som PDF</button><button onclick="window.close()">Stäng</button></div><main><header><div class="brand">SL</div><div><p class="eyebrow">Serverloggen</p><h1>Att följa upp</h1><p class="company"><?=h($company['name'])?></p></div><div class="meta">Skapad<br><strong><?=h($generated)?></strong></div></header><?php if($company['info']!==''):?><section class="company-info"><strong>Bra att veta</strong><p><?=nl2br(h($company['info']))?></p></section><?php endif?><section><div class="summary"><h2>Öppna uppföljningar</h2><span><?=count($rows)?> <?=count($rows)===1?'post':'poster'?></span></div><?php if(!$rows):?><div class="empty">Det finns inga öppna uppföljningar för företaget.</div><?php else:?><div class="items"><?php foreach($rows as $i=>$row):?><article><div class="number"><?=($i+1)?></div><div class="content"><div class="item-head"><h3><?=h($row['server_name'])?></h3><time><?=h($row['log_date'])?></time></div><div class="label">Kommentar från loggen</div><p class="comment"><?=$row['comment']!==''?nl2br(h($row['comment'])):'Ingen kommentar angiven.'?></p><div class="resolution"><span>Åtgärd / anteckning</span></div></div></article><?php endforeach?></div><?php endif?></section><footer>EventLogger - <?=h($company['name'])?> - <?=h($generated)?></footer></main></body></html>
